"""Data models and LangGraph state schemas."""
from typing import List, Optional, Dict, Any, TypedDict
from pydantic import BaseModel, Field


class ResearchPlan(BaseModel):
    """The structured research decomposition generated by the Planner."""
    topic: str = Field(description="The core topic or question being investigated")
    sub_topics: List[str] = Field(description="Key dimensions, angles, or sub-questions to explore")
    hypotheses: List[str] = Field(default_factory=list, description="Initial hypotheses or questions to verify")
    search_queries: List[str] = Field(description="Precise web search queries designed to gather factual evidence")


class SearchResultItem(BaseModel):
    """An individual piece of retrieved web evidence."""
    title: str
    url: str
    snippet: str
    content: Optional[str] = None
    source_query: Optional[str] = None


class EvaluationResult(BaseModel):
    """Self-reflection assessment of retrieved research evidence."""
    is_sufficient: bool = Field(
        description="True if evidence is comprehensive enough to write an authoritative, complete report; False if major gaps remain"
    )
    critique: str = Field(
        description="Detailed reflection on what is well-covered and what information is missing or contradictory"
    )
    missing_aspects: List[str] = Field(
        default_factory=list,
        description="Specific unanswered questions or gaps identified in the current evidence"
    )
    followup_queries: List[str] = Field(
        default_factory=list,
        description="Targeted follow-up search queries to resolve missing gaps (if is_sufficient is False)"
    )


class ResearchState(TypedDict, total=False):
    """State maintained across all LangGraph nodes during the research workflow."""
    task: str
    plan: Optional[ResearchPlan]
    evidence: List[Dict[str, Any]]
    evaluation: Optional[EvaluationResult]
    iteration: int
    max_iterations: int
    final_report: Optional[str]
    logs: List[str]
